# ════════════════════════════════
#        IMPORT FUNCTION
# ════════════════════════════════

def import_all():
    db: Session = database.SessionLocal()
    BASE_URL = os.getenv("BASE_URL", "http://127.0.0.1:8000")

    try:
        print(f"Starting import of {len(stories)} stories and {len(questions)} questions...")
        print("=" * 50)

        # Check if already imported
        existing = db.query(models.ReadingPassage).count()
        if existing > 0:
            print(f"WARNING: {existing} passages already exist in database!")
            confirm = input("Do you want to continue and add more? (yes/no): ")
            if confirm.lower() != "yes":
                print("Import cancelled.")
                return

        # Import stories
        passage_id_map = {}  # maps story id → database passage id

        for i, story in enumerate(stories):
            print(f"[{i+1}/{len(stories)}] Importing: {story['title']}...")

            # Generate TTS audio
            try:
                safe_title = story["title"].replace(" ", "_")[:20]
                audio_filename = f"passage_{safe_title}_{uuid.uuid4().hex[:8]}.mp3"
                audio_path = f"static/{audio_filename}"
                os.makedirs("static", exist_ok=True)
                text_to_speech(story["content"], audio_path)
                audio_url = f"{BASE_URL}/static/{audio_filename}"
                print(f"   ✅ Audio generated")
            except Exception as e:
                audio_url = None
                print(f"   ⚠️ Audio failed: {e}")

            # Save passage to DB
            new_passage = models.ReadingPassage(
                title=story["title"],
                content=story["content"],
                level=story["level"],
                audio_url=audio_url
            )
            db.add(new_passage)
            db.flush()  # get the id without committing

            passage_id_map[story["id"]] = new_passage.id
            print(f"   ✅ Saved to DB with id: {new_passage.id}")

        db.commit()
        print("\n✅ All stories imported successfully!")
        print("=" * 50)

        # Import questions
        print(f"\nImporting {len(questions)} questions...")
        for i, q in enumerate(questions):
            db_passage_id = passage_id_map.get(q["passage_id"])
            if not db_passage_id:
                print(f"⚠️ Passage {q['passage_id']} not found, skipping question")
                continue

            new_question = models.ReadingQuestion(
                passage_id=db_passage_id,
                question_text=q["question_text"],
                option_1=q["option_1"],
                option_2=q["option_2"],
                option_3=q["option_3"],
                correct_answer=q["correct_answer"]
            )
            db.add(new_question)

        db.commit()
        print(f"✅ All {len(questions)} questions imported successfully!")
        print("=" * 50)
        print("\n🎉 IMPORT COMPLETE!")
        print(f"   Stories: {len(stories)}")
        print(f"   Questions: {len(questions)}")
        print(f"   Level 1: 20 stories (ids 1-20)")
        print(f"   Level 2: 20 stories (ids 21-40)")
        print(f"   Level 3: 20 stories (ids 41-60)")

    except Exception as e:
        db.rollback()
        print(f"\n❌ Import failed: {e}")
        raise
    finally:
        db.close()


if __name__ == "__main__":
    import_all()
